          <div className="process-grid">

            {steps.map((step, index) => (
              <div className="process-card" key={index}>

                <div className="process-number">
                  {step.number}
                </div>

                <h3>{step.title}</h3>

                <p>{step.text}</p>

              </div>
            ))}

          </div>

        </div>

      </section>


      {/* CTA */}
      <section className="services-cta">

        <div className="services-cta-content">

          <span>
